package com.coworkhub.config;
import org.springframework.context.annotation.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.beans.factory.annotation.Value;import jakarta.annotation.PostConstruct;import java.time.Clock;
@Configuration public class AppConfig { @Bean @Primary Clock systemClock(){return Clock.systemDefaultZone();} @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean String applicationMode(@Value("${app.mode:development}") String mode){return mode;} @Bean ConfigurationValidator configurationValidator(@Value("${app.mode:development}") String mode,@Value("${jwt.secret:CoWorkHubDevelopmentKeyForJWTSigningOnlyChangeInProduction123456789}") String secret){return new ConfigurationValidator(mode,secret);} static class ConfigurationValidator{private final String mode,secret;ConfigurationValidator(String m,String s){mode=m;secret=s;}@PostConstruct void validate(){if(secret.length()<32)throw new IllegalStateException("JWT secret debe tener al menos 32 caracteres");if(mode==null||mode.isBlank())throw new IllegalStateException("app.mode no puede estar vacío");}}
}
